   390	function buildSessionPath(
   391		entries: SessionEntry[],
   392		leafId?: string | null,
   393		byId?: Map<string, SessionEntry>,
   394	): SessionEntry[] {
   395		const index = buildEntryIndex(entries, byId);
   396		let leaf: SessionEntry | undefined;
   397		if (leafId === null) {
   398			return [];
   399		}
   400		if (leafId) {
   401			leaf = index.get(leafId);
   402		}
   403		leaf ??= entries[entries.length - 1];
   404		if (!leaf) {
   405			return [];
   406		}
   407	
   408		const path: SessionEntry[] = [];
   409		let current: SessionEntry | undefined = leaf;
   410		while (current) {
   411			path.push(current);
   412			current = current.parentId ? index.get(current.parentId) : undefined;
   413		}
   414		path.reverse();
   415		return path;
   416	}
