   519	/** Project one entry into model-visible messages, applying its latest context edit if any. */
   520	export function projectContextEntry(entry: SessionEntry, edit: ContextEditEntry | undefined): AgentMessage[] {
   521		const messages = sessionEntryToContextMessages(entry);
   522		if (!edit) return messages;
   523		const replacement = edit.replacement;
   524		if (replacement === null) return [];
   525	
   526		return messages.map((message) => {
   527			if (
   528				message.role !== "user" &&
   529				message.role !== "assistant" &&
   530				message.role !== "toolResult" &&
   531				message.role !== "custom"
   532			) {
   533				return message;
   534			}
   535			const content =
   536				(message.role === "assistant" || message.role === "toolResult") && typeof replacement.content === "string"
   537					? [{ type: "text" as const, text: replacement.content }]
   538					: replacement.content;
   539			return { ...message, content } as AgentMessage;
   540		});
