   543	/** Build provenance-preserving, compaction-aware model context. */
   544	export function buildSessionProjection(
   545		entries: SessionEntry[],
   546		leafId?: string | null,
   547		byId?: Map<string, SessionEntry>,
   548	): SessionProjection {
   549		const path = buildSessionPath(entries, leafId, byId);
   550		const { thinkingLevel, model } = getSessionContextSettings(path);
   551		const contextEntries = buildContextEntries(entries, leafId, byId);
   552		const edits = new Map<string, ContextEditEntry>();
   553		for (const entry of contextEntries) {
   554			if (entry.type === "context_edit") edits.set(entry.targetId, entry);
   555		}
   556		const projectedEntries = contextEntries.map(
   557			(sourceEntry, index): ProjectedSessionEntry => ({
   558				sourceEntry,
   559				// buildContextEntries() may retain an older compaction entry because its
   560				// raw ID lies inside the newest retained range. Only the newest compaction
   561				// at index zero contributes a checkpoint and summary.
   562				messages:
   563					sourceEntry.type === "compaction" && index > 0
   564						? []
   565						: projectContextEntry(sourceEntry, edits.get(sourceEntry.id)),
   566			}),
   567		);
   568		return {
   569			entries: projectedEntries,
   570			messages: projectedEntries.flatMap((entry) => entry.messages),
   571			thinkingLevel,
   572			model,
   573		};
   574	}
