   576	/** Build the finalized model context from the canonical session projection. */
   577	export function buildSessionContext(
   578		entries: SessionEntry[],
   579		leafId?: string | null,
   580		byId?: Map<string, SessionEntry>,
   581	): SessionContext {
   582		const { messages, thinkingLevel, model } = buildSessionProjection(entries, leafId, byId);
   583		return { messages, thinkingLevel, model };
